        if (!victim.isBlocking()) return;
        var slot = victim.getUsedItemHand() == InteractionHand.MAIN_HAND ? EquipmentSlot.MAINHAND : EquipmentSlot.OFFHAND;
        victim.getUseItem().hurtAndBreak(damage, victim, slot);
    }
